using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using IndianOceanAssets.ShooterSurvival;using Object=UnityEngine.Object;
public static class ExactContent16 {
 static string Json(object v)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{v});
 static void Shot(Camera c,string file){var old=c.targetTexture;var prev=RenderTexture.active;var rt=RenderTexture.GetTemporary(720,1560,24,RenderTextureFormat.ARGB32);Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(720,1560,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,720,1560),0,0);tex.Apply();File.WriteAllBytes(file,tex.EncodeToPNG());}finally{c.targetTexture=old;RenderTexture.active=prev;RenderTexture.ReleaseTemporary(rt);if(tex!=null)Object.DestroyImmediate(tex);}}
 public static object Pair(string folder){if(!EditorApplication.isPlaying||Directory.Exists(folder))throw new Exception("Unused output and actual play required");Directory.CreateDirectory(folder);var d=Object.FindFirstObjectByType<Chapter45Director>();var root=d.transform.Find("Scenery/ContentCycle16 shopping fork infill");if(root==null)throw new Exception("Installed street required");var rs=root.GetComponentsInChildren<Renderer>(true);var states=rs.Select(r=>r.enabled).ToArray();var c=Camera.main;int frame=Time.frameCount;float elapsed=d.Elapsed;try{for(int i=0;i<rs.Length;i++)rs[i].enabled=false;Shot(c,folder+"/before.png");for(int i=0;i<rs.Length;i++)rs[i].enabled=states[i];Shot(c,folder+"/after.png");}finally{for(int i=0;i<rs.Length;i++)rs[i].enabled=states[i];}if(frame!=Time.frameCount||elapsed!=d.Elapsed)throw new Exception("Not same frame");var report=new{exactSamePlayFrame=true,frame,elapsed,d.Distance,d.Lane,scene=d.gameObject.scene.name,cameraPosition=c.transform.position.ToString("R"),cameraRotation=c.transform.rotation.ToString("R"),width=720,height=1560,screenSpaceOverlayUiExcluded=true,before="Installed added renderers disabled only for camera render; original scenery, poses and all gameplay unchanged",after="Installed added renderers restored in same frame",newRendererCount=rs.Length};File.WriteAllText(folder+"/conditions.json",Json(report));return report;}
 public static object PairQueue(string folder){if(!EditorApplication.isPlaying||Directory.Exists(folder))throw new Exception("Fresh actual play/output required");Directory.CreateDirectory(folder);var d=Object.FindFirstObjectByType<Chapter45Director>();var actor=d.transform.Find("DetailedMall_20261003/B1 식당 대기줄/Actor 23 A01_dad");if(!actor.gameObject.activeInHierarchy)throw new Exception("Queue actor not active");var current=actor.GetComponentInChildren<Animator>();var old=d.transform.Find("ContentCycle16 preserved queue visual/Generated role CH09 CalledQueue");var previousParent=old.parent;var position=old.localPosition;var rotation=old.localRotation;var scale=old.localScale;bool oldActive=old.gameObject.activeSelf;var rs=current.GetComponentsInChildren<Renderer>(true);var states=rs.Select(r=>r.enabled).ToArray();var c=Camera.main;int frame=Time.frameCount;float elapsed=d.Elapsed;var animState=current.GetCurrentAnimatorStateInfo(0);try{old.SetParent(actor,false);old.localPosition=Vector3.zero;old.localRotation=Quaternion.identity;old.localScale=Vector3.one;old.gameObject.SetActive(true);var previous=old.GetComponentInChildren<Animator>();previous.Play(animState.fullPathHash,0,animState.normalizedTime);previous.Update(0);for(int i=0;i<rs.Length;i++)rs[i].enabled=false;Shot(c,folder+"/before.png");old.gameObject.SetActive(false);for(int i=0;i<rs.Length;i++)rs[i].enabled=states[i];Shot(c,folder+"/after.png");}finally{old.gameObject.SetActive(false);old.SetParent(previousParent,false);old.localPosition=position;old.localRotation=rotation;old.localScale=scale;old.gameObject.SetActive(oldActive);for(int i=0;i<rs.Length;i++)rs[i].enabled=states[i];}if(frame!=Time.frameCount||elapsed!=d.Elapsed||actor.GetComponentsInChildren<Animator>(true).Length!=1)throw new Exception("Frame or rig restore failed");var report=new{exactSamePlayFrame=true,frame,elapsed,d.Distance,d.Lane,width=720,height=1560,screenSpaceOverlayUiExcluded=true,before="Preserved CH09 visual temporarily posed at current actor with same animation state/time; gameplay simulation unchanged",after="Actual saved CH05 visual",actorAnimatorRestored=true,actorBounds=current.GetComponentInChildren<SkinnedMeshRenderer>().bounds.size.ToString("R")};File.WriteAllText(folder+"/conditions.json",Json(report));return report;}
 public static object Audit(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit only");var setup=UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup();try{UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();var root=d.transform.Find("Scenery/ContentCycle16 shopping fork infill");var meshes=root.GetComponentsInChildren<MeshFilter>(true);float min=float.MaxValue;var touched=new List<string>();foreach(var bay in root.Cast<Transform>()){var group=bay.GetComponent<Chapter45SceneryGroup>();float station=(group.startDistance+group.endDistance)*.5f;d.route.Sample(station,out var center,out var forward);var right=Vector3.Cross(Vector3.up,forward);float branch=d.choices[0].Offset(station,0);foreach(var mf in bay.GetComponentsInChildren<MeshFilter>(true)){foreach(var v in mf.sharedMesh.vertices){float lateral=Vector3.Dot(mf.transform.TransformPoint(v)-center,right)-branch;min=Mathf.Min(min,Mathf.Abs(lateral)-d.choices[0].branchHalfWidth);if(Mathf.Abs(lateral)<d.choices[0].branchHalfWidth)touched.Add(bay.name);}}}if(touched.Count!=0||root.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Lane intersection");return new{addedModelTriangles=meshes.Sum(m=>m.sharedMesh.triangles.Length/3),uniqueMeshes=meshes.Select(m=>m.sharedMesh).Distinct().Count(),renderers=root.GetComponentsInChildren<Renderer>(true).Length,materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().Count(),addedColliders=0,minimumSideClearanceToFullPlayableLane=min,all21StationsChecked=true,scope="Saved mesh vertex lateral extents at each storefront center vs actual offset + branchHalfWidth; no device performance claim"};}finally{UnityEditor.SceneManagement.EditorSceneManager.RestoreSceneManagerSetup(setup);}}
